function Admin() {
  const path = useLocation().pathname; const { notify } = useAuth(); const [data, setData] = useState(null); const [error, setError] = useState('');
  const section = path.split('/')[2] || 'overview';
  const endpoint = section === 'users' ? '/admin/users' : section === 'providers' ? '/admin/providers' : section === 'listings' ? '/admin/listings' : section === 'reservations' ? '/admin/reservations' : section === 'audit' ? '/admin/audit' : '/admin/overview';
  const titles = { overview: 'Platform overview', users: 'Member accounts', providers: 'Food partners', listings: 'Listing moderation', reservations: 'Reservations', audit: 'Admin activity' };
  const refresh = () => { setError(''); request(endpoint).then(setData).catch(e => setError(e.message)); };
  useEffect(refresh, [endpoint]);
  const update = async (url, body, message) => { try { await request(url, { method: 'PATCH', body: JSON.stringify(body) }); notify(message); refresh(); } catch (e) { notify(e.message); } };
  const rows = data?.items || [];
  return <DashboardLayout role="admin" title={titles[section] || 'Platform overview'} subtitle="A clear view of the marketplace, from one place."><div className="account-nav"><Link to="/admin">Overview</Link><Link to="/admin/users">Members</Link><Link to="/admin/providers">Food partners</Link><Link to="/admin/listings">Listings</Link><Link to="/admin/reservations">Reservations</Link><Link to="/admin/audit">Audit history</Link></div>{error ? <div className="notice error">{error}</div> : !data ? <div className="skeleton-card"/> : section === 'overview' ? <><div className="metric-grid">{[['Members', data.users], ['Food partners', data.providers], ['Awaiting approval', data.pendingProviders], ['Listings', data.listings], ['Reservations', data.reservations]].map(([label,value]) => <div className="metric-card" key={label}><small>{label}</small><strong>{value ?? '—'}</strong></div>)}</div><h3 className="table-heading">Recent admin actions</h3>{data.recentActions?.length ? <div className="admin-table">{data.recentActions.map(log => <div className="admin-row" key={log._id}><div><b>{log.summary}</b><small>{log.actor?.name || 'Admin'} · {shortDate(log.createdAt)}</small></div><span>{log.action}</span></div>)}</div> : <div className="empty"><h3>No admin actions recorded yet</h3><p>Provider approvals and moderation decisions will appear here.</p></div>}</> : section === 'users' || section === 'providers' ? rows.length ? <div className="admin-table">{rows.map(user => <div className="admin-row" key={user._id}><div><b>{user.name}</b><small>{user.email} · {user.role} · Joined {shortDate(user.createdAt)}</small></div><span className={`status-pill ${user.status}`}>{user.status}</span>{section === 'providers' && <span className={`status-pill ${user.providerApproved ? 'active' : 'paused'}`}>{user.providerApproved ? 'approved' : 'pending'}</span>}<div className="admin-actions">{section === 'providers' && <button className="small-action" onClick={() => update(`/admin/providers/${user._id}/approval`, { approved: !user.providerApproved }, user.providerApproved ? 'Provider approval revoked.' : 'Food partner approved.')}>{user.providerApproved ? 'Revoke' : 'Approve'}</button>}<button className="small-action secondary-action" onClick={() => update(`/admin/users/${user._id}/status`, { status: user.status === 'active' ? 'suspended' : 'active' }, user.status === 'active' ? 'Account suspended.' : 'Account reactivated.')}>{user.status === 'active' ? 'Suspend' : 'Reactivate'}</button></div></div>)}</div> : <div className="empty"><h3>No accounts to show</h3></div> : section === 'listings' ? rows.length ? <div className="admin-table">{rows.map(item => <div className="admin-row" key={item._id}><div><b>{item.title}</b><small>{item.provider?.name || 'Food partner'} · {item.category} · {item.available} portions · {money(item.price)}</small></div><span className={`status-pill ${item.status}`}>{item.status}</span>{['active','paused'].includes(item.status) && <button className="small-action" onClick={() => update(`/admin/listings/${item._id}/status`, { status: item.status === 'active' ? 'paused' : 'active' }, item.status === 'active' ? 'Listing paused.' : 'Listing reactivated.')}>{item.status === 'active' ? 'Pause' : 'Reactivate'}</button>}</div>)}</div> : <div className="empty"><h3>No listings to review</h3></div> : section === 'reservations' ? rows.length ? <div className="admin-table">{rows.map(item => <div className="admin-row" key={item._id}><div><b>{item.listingTitle}</b><small>{item.reference} · {item.customer?.name || 'Customer'} → {item.provider?.name || 'Partner'} · {item.quantity} portions</small><small>{shortDate(item.pickupStart)}</small></div><span className={`status-pill ${item.status}`}>{item.status}</span><strong>{money(item.total)}</strong></div>)}</div> : <div className="empty"><h3>No reservations yet</h3></div> : rows.length ? <div className="admin-table">{rows.map(log => <div className="admin-row" key={log._id}><div><b>{log.summary}</b><small>{log.actor?.name || 'Admin'} · {log.targetType} · {shortDate(log.createdAt)}</small></div><span>{log.action}</span></div>)}</div> : <div className="empty"><h3>No audit events recorded yet</h3></div>}</DashboardLayout>;
}
function DashboardLayout({ role, title, subtitle, children }) { return <main className="dashboard"><aside className="dashboard-rail"><Mark/><span className="rail-label">{role === 'account' ? 'YOUR TABLE' : role.toUpperCase()}</span>{(role === 'account' ? [['/account','Overview'],['/account/reservations','Reservations'],['/account/favorites','Saved'],['/account/profile','Your details'],['/account/notifications','Notifications']] : role === 'provider' ? [['/provider','Overview'],['/provider/listings','Listings'],['/provider/reservations','Reservations'],['/provider/analytics','Analytics'],['/provider/profile','Partner profile']] : [['/admin','Overview'],['/admin/users','Members'],['/admin/providers','Food partners'],['/admin/listings','Listings'],['/admin/reservations','Reservations']]).map(([to,label]) => <Link key={to} to={to} className={window.location.pathname === to ? 'rail-link active' : 'rail-link'}>{label}<ArrowUpRight size={14}/></Link>)}<Link className="rail-back" to="/explore"><ArrowLeft size={14}/> Back to the menu</Link></aside><section className="dashboard-main"><div className="dashboard-heading"><div><span className="eyebrow"><span className="eyebrow-dot"/> A LITTLE SPACE OF YOUR OWN</span><h1>{title}</h1><p>{subtitle}</p></div><Link to="/explore" className="button button-outline button-small">Find food <ArrowUpRight size={15}/></Link></div>{children}</section></main>; }

function InfoPage({ kind }) { const how = kind === 'how'; return <main className="info-page"><div className="eyebrow"><span className="eyebrow-dot"/> {how ? 'THREE SIMPLE STEPS' : 'A LITTLE ABOUT US'}</div><h1>{how ? <>A good find<br/><em>is closer than you think.</em></> : <>A little more care<br/><em>goes a long way.</em></>}</h1><p>{how ? 'Discover surplus food from your neighbourhood, reserve a portion, and pick it up fresh during the time the kitchen sets.' : 'LastPlate brings local kitchens and food lovers together around one simple idea: good food deserves every chance to be enjoyed.'}</p><div className="info-cards">{(how ? [['01','Find something delicious','Browse fresh surplus food listed by kitchens nearby.'],['02','Reserve your portion','Choose a quantity and get a pickup reference from the kitchen.'],['03','Pick it up fresh','Visit during the listed pickup window and pay the provider at collection.']] : [['For food lovers','Discover great local food at prices that make room for another treat.'],['For local kitchens','Share surplus portions, meet your neighbours, and recover value.'],['For good food','Make the most of what’s already been lovingly prepared.']]).map(([a,b,c]) => <article key={a}><span>{a}</span><h3>{b}</h3><p>{c}</p></article>)}</div><Link to="/explore" className="button button-dark">Find a good thing <ArrowRight size={16}/></Link></main>; }
function NotFound() { return <main className="info-page"><span className="eyebrow">A WRONG TURN, PERHAPS</span><h1>That page has<br/><em>left the menu.</em></h1><p>Let’s find you something good instead.</p><Link to="/explore" className="button button-dark">Explore food <ArrowRight size={16}/></Link></main>; }

createRoot(document.getElementById('root')).render(<React.StrictMode><App/></React.StrictMode>);
